  ('en-pt', 'en-f155', 'frase', 'C2', array['gramática', 'formal']::text[], null, '5f56f744', array['Apesar de todo o talento, ele nunca chegou lá.', 'Com todo o talento, ele chegou bem longe.', 'Faltou talento para ele chegar lá.', 'Por causa do talento, ele nunca chegou lá.', 'Só com talento ele chegou lá.']::text[]),
  ('en-pt', 'en-f156', 'frase', 'C2', array['gramática', 'formal']::text[], null, '1ba5ae42', array['Ela não seria meticulosa se pudesse.', 'Ela não é meticulosa de jeito nenhum.', 'Ela não é nada além de meticulosa.', 'Ela é meticulosa, isso não se discute.', 'Ela é meticulosa, mas nada além disso.']::text[]),
  ('en-pt', 'en-f157', 'frase', 'C2', array['gramática', 'formal', 'social']::text[], null, 'c54f6418', array['Isso não foi dito para mim.', 'Não cabe a mim dizer.', 'Não quero dizer isso.', 'Não tenho nada a dizer.', 'Não é para eu dizer isso.']::text[]),
  ('en-pt', 'en-f158', 'frase', 'C2', array['gramática', 'formal']::text[], null, 'ce98a9cb', array['Como não é assim, temos que decidir.', 'Já que é assim, temos que decidir.', 'Nesse caso, temos que decidir.', 'Se for assim, temos que decidir.', 'Seja como for, temos que decidir.']::text[]),
  ('en-pt', 'en-f159', 'frase', 'C2', array['gramática', 'formal']::text[], null, '3cf21eb0', array['Ele ficou bem mais sábio.', 'Ele ficou sem entender nada.', 'Ele ficou um pouco mais esperto.', 'Ele não era o mais sábio.', 'Ele voltou para casa sabendo tudo.']::text[]),
  ('en-pt', 'en-f160', 'frase', 'C2', array['expressão', 'formal']::text[], null, '5c19acb0', array['Isso está em toda parte.', 'Isso não está nem aqui nem ali.', 'Isso não fica em lugar nenhum.', 'Isso não vem ao caso.', 'Isso é indecisão pura.']::text[]),
  ('en-pt', 'en-f161', 'frase', 'C2', array['expressão', 'formal']::text[], null, 'd07494bf', array['Estou longe de reclamar disso.', 'Isso está longe de ser uma reclamação.', 'Já reclamei demais disso.', 'Longe de mim reclamar.', 'Vim de longe para reclamar.']::text[]),
  ('en-pt', 'en-f162', 'frase', 'C2', array['gramática', 'formal', 'trabalho']::text[], null, '1bd0d062', array['Ele pediu desculpa mais cedo do que se demitiu.', 'Ele prefere se demitir a pedir desculpa.', 'Ele se demite assim que pedir desculpa.', 'Ele se demitiu antes de pedir desculpa.', 'Ele vai se demitir logo depois de pedir desculpa.']::text[]),
  ('en-pt', 'en-f163', 'frase', 'C2', array['expressão', 'formal']::text[], null, '5654623e', array['Aos poucos, funcionou.', 'Com folga, funcionou.', 'De longe, foi o que funcionou.', 'De modo geral, funcionou.', 'Por pouco, funcionou.']::text[]),
  ('en-pt', 'en-f164', 'frase', 'C2', array['expressão', 'formal']::text[], null, 'c6e26de5', array['Depois de dizer tudo, fiquei surpreso.', 'Para dizer o máximo, fiquei surpreso.', 'Para dizer o mínimo, fiquei surpreso.', 'Para não dizer nada, fiquei surpreso.', 'Sem dizer nada, fiquei surpreso.']::text[]),
  ('en-pt', 'en-f165', 'frase', 'C2', array['gramática', 'formal']::text[], null, '97e2c8d4', array['Ele avisou que ela estaria presente.', 'Ele insistiu em estar presente com ela.', 'Ele insistiu que ela estava presente.', 'Ele insistiu que ela estivesse presente.', 'Ele reparou que ela estava presente.']::text[]),
  ('en-pt', 'en-f166', 'frase', 'C2', array['gramática', 'formal', 'social']::text[], null, '37a3d13b', array['Deve ligar mesmo sem precisar de nada.', 'Precisando ou não, é para ligar.', 'Se for para ligar, precise de alguma coisa.', 'Se precisar de alguma coisa, é só ligar.', 'Você deveria ligar se precisar de alguma coisa.']::text[]),
  ('en-pt', 'en-f167', 'frase', 'C1', array['expressão', 'social']::text[], null, '7bf2bece', array['Entendi o que você quis dizer.', 'Eu levo isso que você ouviu.', 'Imagino que você já saiba.', 'Me conta o que aconteceu.', 'Vou aceitar o que você ouviu.']::text[]),
  ('en-pt', 'en-f168', 'frase', 'C1', array['expressão']::text[], null, '19e43213', array['Ele foi embora sem dizer nada.', 'Isso não se diz de jeito nenhum.', 'Isso vai sem avisar.', 'Nem precisa dizer.', 'Ninguém disse isso ainda.']::text[]),
